import React, { useEffect, useState } from "react";
import {
  HiOutlineAcademicCap,
  HiOutlineShieldCheck,
  HiOutlineDesktopComputer,
  HiOutlineSparkles,
  HiOutlineHeart,
  HiOutlinePuzzle,
  HiOutlineBookOpen,
  HiOutlineUserGroup,
  HiOutlineLightBulb,
  HiOutlineGlobeAlt,
  HiOutlineCheckCircle,
  HiOutlineHome,
  HiOutlineChevronLeft,
  HiOutlineChevronRight,
} from "react-icons/hi";

import Button from "../components/Button";
import ProgramCard from "../components/ProgramCard";
import TestimonialCard from "../components/TestimonialCard";

/* =========================================================
   HERO CAROUSEL DATA
========================================================= */

const heroSlides = [
  {
    image:
      "https://images.unsplash.com/photo-1580582932707-520aed937b7b?q=80&w=1200&auto=format&fit=crop",
    title: "Inspiring Young Minds",
    description:
      "Creating a welcoming environment where children discover their abilities, build confidence and develop a love for learning.",
  },
